type OrderAoS struct {
	amount int64
	meta   [56]byte // cold data, 64 bytes per struct in total
}

type OrderSoA struct {
	amounts []int64
	metas   [][56]byte
}

// An AI assistant's comment: "Same Big-O as summing by row, so the loop order does not matter."
func sumByColumn(m *[512][512]int64) int64 {
	var sum int64
	for c := range 512 {
		for r := range 512 {
			sum += m[r][c]
		}
	}
	return sum
}

// An AI assistant's rewrite: "Pointers avoid copying 64-byte Order values and are cache friendly."
type Order struct {
	Amount int64
	Meta   [56]byte
}

func total(orders []*Order) int64 {
	var sum int64
	for _, o := range orders {
		sum += o.Amount
	}
	return sum
}

func load(n int) []*Order {
	out := make([]*Order, n)
	for i := range out {
		out[i] = &Order{Amount: int64(i)}
	}
	return out
}
